<?php

$finder = new PhpCsFixer\Finder()
    ->in(__DIR__)
    ->exclude('var')
    // Archived task material and legacy-import reference code. It is kept to compare against the
    // legacy source, so it must keep the formatting of that source.
    ->exclude('aitasks')
    // Generated by Symfony on every cache warm-up. Our changes there would be lost.
    ->notPath('config/reference.php')
    // Skip files git ignores.
    ->ignoreVCSIgnored(true)
;

return new PhpCsFixer\Config()
    // In var/, not in the project folder: in the Docker setup var/ is not on the disk, so a run changes no file there.
    ->setCacheFile(__DIR__ . '/var/.php-cs-fixer.cache')
    ->setRiskyAllowed(true)
    // Our own rules, in tools/php-cs-fixer/ (see docs/php-cs-fixer.md).
    ->registerCustomFixers([
        new App\Tools\PhpCsFixer\AttributeArgumentsPerLineFixer(),
    ])
    // Docs on available rules: https://github.com/PHP-CS-Fixer/PHP-CS-Fixer
    ->setRules([
        '@Symfony' => true,
        '@Symfony:risky' => true,
        'declare_strict_types' => true,
        'static_lambda' => false,
        'yoda_style' => false,
        // @Symfony aligns PHPDoc tags vertically, padding `@param` with spaces so the types and
        // variable names line up. Owner decision 2026-11-24: no padding. `left` is what removes it;
        // turning the rule off would only stop new padding and leave what is already there.
        'phpdoc_align' => ['align' => 'left'],
        // Part of @Symfony:risky. It prefixes the compiler-optimized natives - sprintf(),
        // count(), in_array(), array_key_exists(), is_string() ... - with a backslash. We do
        // not want that: `include: []` marks no function as one that needs the backslash, and
        // `strict: true` removes it from every native function call that has it.
        'native_function_invocation' => ['include' => [], 'strict' => true],
        // Global classes and constants are written as `\DateTimeImmutable`, `\JSON_THROW_ON_ERROR`,
        // as @Symfony does. Global functions are left as they are, so `sprintf()` stays as it is.
        'global_namespace_import' => [
            'import_classes' => false,
            'import_constants' => false,
            'import_functions' => null,
        ],
        // Part of @Symfony, which only shortens an FQCN that is already imported. `import_symbols`
        // adds the missing `use` as well, so a namespaced class is never written inline:
        // `\App\Shared\...\ExceptionMessageTranslator $x` becomes a `use` plus
        // `ExceptionMessageTranslator $x`. Single-segment global classes are not namespaced and stay
        // inline as `\DateTimeImmutable`, which is what `global_namespace_import` above asks for.
        'fully_qualified_strict_types' => ['import_symbols' => true],
        // Part of @Symfony. It lowercases the `@param` text and drops its trailing dot. The DTO
        // `@param` texts become the OpenAPI field descriptions, so it stays off.
        'phpdoc_annotation_without_dot' => false,
        // Part of @Symfony. It joins a multi-line `throw` into one line, however long it gets.
        'single_line_throw' => false,
        // @Symfony joins a multi-line `implements`/`extends` list into one line, however long it gets.
        'class_definition' => ['single_line' => false],
        // @Symfony writes `'a'.$b`. We keep one space around the concatenation operator: `'a' . $b`.
        'concat_space' => ['spacing' => 'one'],
        // PHPStan reads `@var` and `(@)phpstan-ignore-next-line` only from `/** */` docblocks,
        // so they must not become plain `/* */` comments. (Replace `(@)` with `@`)
        'phpdoc_to_comment' => [
            'ignored_tags' => ['var', 'phpstan-ignore-next-line'],
        ],
        // The pre-commit `trailing-whitespace` hook strips trailing spaces inside multi-line
        // strings (SQL, API descriptions) too. Doing it here keeps the fixer output and the
        // committed code the same.
        'no_trailing_whitespace_in_string' => true,
        // Part of @Symfony. It takes a `/* ****** */` separator line for an empty comment and
        // removes it. We use these separators, so it stays off.
        'no_empty_comment' => false,
        // An empty body stays on on as `) {` and `}` on two lines instead of  `) {}`
        'single_line_empty_body' => false,
        // @Symfony writes a space after a cast: `(int) $value`. We write it without: `(int)$value`.
        'cast_spaces' => ['space' => 'none'],
        // An attribute without arguments has no empty parentheses: `#[Assert\NotBlank]`, not
        // `#[Assert\NotBlank()]`.
        'attribute_empty_parentheses' => ['use_parentheses' => false],
        // Part of @Symfony:risky, which strips the `b` flag from fopen() modes, turning
        // fopen($source, 'rb') into fopen($source, 'r') in six files. This project streams binary
        // data - Sodium-encrypted case attachments (SodiumStreamCipher), local and S3 file storage,
        // the log browser - where `rb`/`wb` is what the code means. The flag is a no-op on Linux
        // but not on every platform, and a silent switch to text mode would corrupt attachments.
        'fopen_flags' => ['b_mode' => true],
        // Part of the @Symfony sets, which drops a `@param` that only repeats the native type.
        // `/** @param mixed $data */` on an API Platform processor looks exactly like that, but it
        // is load bearing: without it PHPStan inherits the narrower generic type that
        // ProcessorInterface::process() declares, and then reads the defensive
        // `$data instanceof <Input>` guard as always true. Removing those six annotations under
        // Users/Presentation/Api/State produced 5 PHPStan errors in a measured run. The rule's
        // `allow_mixed` option does not protect them (checked: it still removes them), and the
        // alternatives are worse - weakening phpstan.neon.dist is forbidden by AGENTS.md, and
        // rewriting the guards or adding `@phpstan-param` would turn a formatting change into a
        // code change. The rule had only two other findings, so it is off.
        'no_superfluous_phpdoc_tags' => false,
    ])
    ->setFinder($finder);
